 {r.phase==='COUNTDOWN'&&<><p className="subtle">Installe-toi. Le départ arrive.</p><div className="big-count">{remaining}</div><p className="target">{targetLabel(t.ex,t.entry)}{hasWeight(t.ex)&&!isGuided(t)&&` · ${fmt(taskLoad(r,t,data.settings.barKg))} kg`}</p><div className="countdown-actions"><button className="primary" onClick={()=>updateRun(run=>startExecution(run))}><Play size={22}/> Lancer maintenant</button>{hasLoad(t.ex)&&!isGuided(t)&&<button className="secondary" onClick={()=>updateRun(x=>({...x,phase:'CHARGE',deadline:null}))}>Modifier la charge</button>}</div></>}
 {r.phase==='EXECUTION'&&<><div className={'execution-target '+(measure==='execution'?'execution-free':'')}><strong>{activeCycle?fmtTime(activeCycle.remaining):measure==='duration'?fmtTime(remaining):measure==='reps'?t.reps:measure==='distance'?fmt(distanceFor(t.ex,t.entry)):'À toi'}</strong><span>{activeCycle?(activeCycle.contract?'Contraction · deux pieds':'Relâchement · deux pieds'):measure==='duration'?'durée restante':measure==='reps'?'mouvements à réaliser':measure==='distance'?'mètres':'exécution libre'}</span></div>{hasLoad(t.ex)&&!isGuided(t)&&<p className="target">{hasWeight(t.ex)?`${fmt(taskLoad(r,t,data.settings.barKg))} kg`:r.bands[t.ex.id]||'Élastique'}</p>}{activeCycle&&<p className="cycle-count">Cycle {activeCycle.index} / {activeCycle.count} · {fmtTime(remaining)} au total</p>}{measure==='duration'&&<TimerControls onPause={pause} onRestart={()=>restart()}/>} {measure==='reps'&&!isGuided(t)&&<p className="elapsed">{fmtTime(elapsed)}</p>}<ExerciseHelp ex={t.ex}/><p className="set-note">{t.entry.note||(r.reduced&&!t.approach&&measure==='reps'?'Volume réduit · garde 3 à 4 répétitions en réserve.':!t.approach&&t.ex.categorie==='force'&&measure==='reps'?(r.model.id.startsWith('bas')?'Garde 2 répétitions en réserve.':'Descente contrôlée, sans élan.'):'À ton rythme, sans forcer.')}</p><button className="primary" onClick={executionDone}><Check size={22}/> {t.warmup?'Activité terminée · suite':measure==='duration'?'Terminer maintenant':measure==='reps'&&!isGuided(t)?'Série terminée':measure==='distance'?'Parcours terminé':'Exécution terminée'}</button></>}
 {r.phase==='VALIDATION'&&<div onPointerDown={touchAuto} onKeyDown={touchAuto}>{r.restDeadline&&<p className="rest-in-validation"><Clock size={17}/> Le repos a commencé · {fmtTime(restRemaining)} restantes</p>}<p className="subtle">{measure==='reps'?'Combien de répétitions ?':measure==='duration'?'Durée réalisée · tu peux l’ajuster.':measure==='distance'?'Distance réalisée · tu peux l’ajuster.':'Exécution terminée.'}</p>{measure==='reps'?<><Stepper large label="Répétitions effectuées" value={r.reps} onChange={v=>updateRun(x=>({...x,reps:v,auto:false,deadline:null}))}/>{!t.approach&&<div className="rir-line"><label htmlFor="rir">Répétitions en réserve <span>(facultatif)</span></label><input id="rir" type="number" min="0" max="10" inputMode="numeric" value={r.rir??''} onChange={e=>updateRun(x=>({...x,rir:e.target.value===''?null:Math.max(0,Math.min(10,Number(e.target.value))),auto:false,deadline:null}))}/></div>}</>:measure==='duration'?<Stepper large label="Durée réalisée" unit="s" value={r.duration_s??Math.max(0,Math.round(((r.executionEnd??r.phaseAt)-(r.executionAt??r.phaseAt))/1000))} onChange={v=>updateRun(x=>({...x,duration_s:v,auto:false,deadline:null}))}/>:measure==='distance'?<Stepper large label="Distance réalisée" unit="m" step={.5} value={r.distance_m??distanceFor(t.ex,t.entry)} onChange={v=>updateRun(x=>({...x,distance_m:v,auto:false,deadline:null}))}/>:<p className="execution-confirmation"><CheckCheck size={36}/> Activité réalisée</p>}{r.auto?<><Progress value={Math.min(100,remaining/AUTO_VALIDATE_SECONDS*100)}/><p className="auto-note">Validation automatique dans {remaining} s · touche pour corriger</p></>:<p className="auto-note">À toi de valider.</p>}<button className="primary" onClick={()=>validate(false)}><Check size={22}/> {measure==='reps'?'Confirmer la série':'Confirmer l’exécution'}</button></div>}
 {r.phase==='REST'&&<><div className="rest-clock"><span>{fmtTime(remaining)}</span><small>repos restant</small></div><TimerControls label="le repos" onPause={pause} onRestart={()=>restart('rest')}/>{following&&<div className="next-load"><small>PROCHAINE SÉRIE · {following.ex.nom}</small><strong>{hasWeight(following.ex)?r.loads[following.ex.id]!==undefined?`${following.ex.type_charge==='halteres'?'Prépare les haltères à':'Charge la barre à'} ${fmt(taskLoad(r,following,data.settings.barKg))} kg${following.approach&&following.factor===0?' · à vide':''}`:'Charge à choisir au début de l’exercice':hasResistance(following.ex)?r.bands[following.ex.id]||'Élastique':targetLabel(following.ex,following.entry)}</strong>{hasWeight(following.ex)&&<span>{following.reps} répétitions{following.approach?' · approche':' · travail'}</span>}</div>}{activeFiller?<div className="filler"><div className="filler-heading"><span className="pill">PENDANT LE REPOS</span><span>{activeFiller.side!=='bilateral'?'Côté '+activeFiller.side:activeFiller.entry.cycle?'Deux pieds ensemble':'Exécution'}{activeFiller.entry.series>1?' · '+activeFiller.index+' / '+activeFiller.entry.series:''}</span></div><h2>{activeCycle?fmtTime(activeCycle.remaining):measureFor(activeFiller.ex,activeFiller.entry)==='duration'?fmtTime(Math.max(0,Math.ceil(((r.fillerDeadline??now)-(r.pausedAt??now))/1000))):'À réaliser'}</h2>{activeCycle&&<p className="cycle-count">{activeCycle.contract?'Contracte les deux pieds':'Relâche les deux pieds'} · Cycle {activeCycle.index} / {activeCycle.count}</p>}{!activeCycle&&measureFor(activeFiller.ex,activeFiller.entry)==='distance'&&<p className="subtle">{targetLabel(activeFiller.ex,activeFiller.entry)}{activeFiller.side!=='bilateral'?' de ce côté':''}</p>}{activeFiller.seconds>0&&<TimerControls label="l’intercalaire" onPause={pause} onRestart={()=>restart()}/>}<ExerciseHelp ex={activeFiller.ex}/><button className="primary" onClick={()=>finishFiller(false)}><Check size={20}/> {t.fillers?.[r.fillerIndex+1]?'Étape terminée · suite':'Intercalaire terminé'}</button></div>:<><div className="breathe" aria-hidden="true"><span/></div><p className="subtle">{t.fillers?.length?'Intercalaire terminé. Profite du repos restant.':'Profite de ce temps pour récupérer.'}</p></>}<button className="secondary" onClick={advance}><SkipForward size={18}/> Passer le repos</button>{activeFiller&&<button className="text-button skip-filler" onClick={()=>updateRun(x=>({...x,fillerIndex:t.fillers?.length??0,fillerDeadline:null}))}>Ignorer cet intercalaire</button>}</>}
 {r.phase==='REVIEW'&&<div onPointerDown={touchAuto} onKeyDown={touchAuto}><p className="subtle">{measure==='reps'?'Tes séries. Un dernier regard avant la suite.':'Tes passages. Un dernier regard avant la suite.'}</p><SeriesTable rows={primaryRows(r.rows,catalogue).filter(x=>x.exercice_id===t.ex.id)} catalogue={catalogue} onChange={editRow}/><h3 className="feedback-title">{hasLoad(t.ex)?'La charge était comment ?':'Comment s’est passée l’exécution ?'}</h3><FeedbackBar load={hasLoad(t.ex)} value={r.retours[t.ex.id]??'ok'} onChange={v=>updateRun(x=>({...x,retours:{...x.retours,[t.ex.id]:v},auto:false,deadline:null}))}/>{r.auto&&<><Progress className="auto-progress" value={Math.min(100,remaining/AUTO_VALIDATE_SECONDS*100)}/><p className="auto-note">« {hasLoad(t.ex)?'Charge bonne':'Bien'} » validé dans {remaining} s</p></>}<button className="primary" onClick={reviewNext}><Check size={20}/> Continuer</button></div>}
